SELECT COUNT(*) as total_followups FROM follow_ups;
SELECT COUNT(*) as leads_with_followup_date FROM leads WHERE followUpDate IS NOT NULL;
SELECT f.lead_id, f.due_date, f.status, l.name as lead_name FROM follow_ups f JOIN leads l ON f.lead_id = l.id WHERE f.status = 'Pending' ORDER BY f.due_date LIMIT 15;

